package vn.eduassistant.backend.web;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import vn.eduassistant.backend.config.AppConfig;
import vn.eduassistant.backend.core.ApiResponse;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import vn.eduassistant.backend.service.*;
import javax.servlet.http.HttpServletRequest;
import java.time.Instant;
import java.util.*;

@RestController
public class SystemController {
    private final AuthService auth;private final AddressService addresses;private final AppConfig config;private final JdbcSupport db;private final PolicyService policy;private final VerifyHarnessService harness;private final BenchmarkService benchmark;private final RedisSupport redis;
    public SystemController(AuthService auth,AddressService addresses,AppConfig config,JdbcSupport db,PolicyService policy,VerifyHarnessService harness,BenchmarkService benchmark,RedisSupport redis){this.auth=auth;this.addresses=addresses;this.config=config;this.db=db;this.policy=policy;this.harness=harness;this.benchmark=benchmark;this.redis=redis;}
    @RequestMapping(value="/api/health",method={RequestMethod.GET,RequestMethod.HEAD}) public Map<String,Object> health(){boolean database=false;try{database=db.one("SELECT 1 AS ok")!=null;}catch(Exception ignored){}boolean redisOk=redis.connected();return UserService.map("status",database?"healthy":"degraded","server","EduAssistant Java Enterprise Engine","version","3.0.0","timestamp",Instant.now().toString(),"modules",UserService.map("jwtAuth","Active & Secure","twoFactorTOTP","Active (No-Backdoor)","geminiAI","Mode: "+config.aiMode,"ruleEngine","Active (5 Strict Reasons)","database",database?"PostgreSQL: connected":"PostgreSQL: unavailable","redis",redisOk?"Connected":"Disabled or unavailable"));}
    @GetMapping({"/api/system/ai-status","/api/ai/status"}) public ResponseEntity<?> aiStatus(HttpServletRequest request){auth.currentUser(request);boolean configured=config.geminiApiKey.length()>10;return ApiResponse.success(200,"Lấy trạng thái AI thành công.",UserService.map("provider","Google Gemini Live API","isConfigured",configured,"hasApiKey",configured,"currentMode",configured?"live":"fallback","operationalStatus",configured?"CONFIGURED":"NOT_CONFIGURED","displayLabel",configured?"Gemini configured":"AI unavailable – Safe Human Review","model",AppConfig.value("GEMINI_TEXT_MODEL","gemini-3.8-flash"),"fallbackParser","Deterministic Vietnamese Administrative Address Parser","failSafeEnabled",true));}
    @GetMapping("/docs") public org.springframework.web.servlet.view.RedirectView docs(){return new org.springframework.web.servlet.view.RedirectView("/swagger-ui.html");}
    @PostMapping({"/api/system/ai-mode","/api/ai/mode"}) public ResponseEntity<?> aiMode(HttpServletRequest request){auth.require(request,"ADMIN");return ApiResponse.success(200,"Chế độ AI hiện được quản lý tự động qua cơ chế Fail-Safe (Gemini Live với Deterministic Fallback). Endpoint này đã được deprecated an toàn.",UserService.map("mode","live","deprecated",true,"failSafeActive",true));}
    @PostMapping("/api/ai/normalize-address") public ResponseEntity<?> normalize(@RequestBody Map<String,Object>req,HttpServletRequest request){auth.currentUser(request);return ApiResponse.success(200,"Chuẩn hóa địa chỉ thành công.",addresses.normalize(Json.str(req.get("rawAddress")),Json.str(req.get("addressType"))));}
    @RequestMapping(value="/api/verify/run",method={RequestMethod.GET,RequestMethod.POST}) public ResponseEntity<?> verify(){return ApiResponse.success(200,"Chạy Verify Harness xác định thành công.",harness.run());}
    @GetMapping("/api/judge/summary") public ResponseEntity<?> judge(){boolean dbOk=false;try{dbOk=db.one("SELECT 1 AS ok")!=null;}catch(Exception ignored){}boolean gemini=config.geminiApiKey.length()>10,open=config.openRouterApiKey.length()>10;Map<String,Object>bench=readJson("benchmark/results/latest.json");Map<String,Object>benchSummary=bench==null?UserService.map("benchmarkType","DETERMINISTIC_TRACK_A_DECISION_BENCHMARK","aiCallsPerformed",false,"evaluationTarget","ESCALATION_DECISION_POLICY","scenarioCount",null,"totalCases",null,"decisionAccuracy",null,"automationRate",null,"escalationRate",null,"missedEscalationRate",null,"unnecessaryEscalationRate",null,"correctCases",null,"expectedEscalations",null,"missedEscalationCount",null,"expectedAutoApprovals",null,"unnecessaryEscalationCount",null,"benchmarkRunId",null,"timestamp",null,"executionTimeSec",null,"datasetSha256",null):bench;Map<String,Object>manifest=readJson("benchmark/holdout/manifest.json"),holdout=readJson("benchmark/holdout/results/latest.json");Map<String,Object>hold=manifest!=null&&holdout!=null?UserService.map("status","COMPLETED","datasetVersion",manifest.get("version"),"datasetSha256",manifest.get("sha256"),"scenarioCount",manifest.get("scenarioCount"),"timestamp",holdout.get("timestamp"),"metrics",holdout.get("metrics")):UserService.map("status","NOT_RUN","datasetVersion",null,"datasetSha256",null,"scenarioCount",null,"timestamp",null,"metrics",null);return ApiResponse.success(200,"Public judge summary loaded.",UserService.map("apiStatus","AVAILABLE","databaseStatus",dbOk?"AVAILABLE":"UNAVAILABLE","ai",UserService.map("configured",gemini||open,"status",gemini||open?"CONFIGURED":"NOT_CONFIGURED","providers",UserService.map("gemini",gemini,"openrouter",open)),"adaptiveThreshold",policy.threshold(),"adaptivePolicy",policy.summary(),"benchmark",benchSummary,"frozenHoldout",hold,"verifyHarness",UserService.map("scenarioCount",9,"type","DETERMINISTIC_RULE_ENGINE_VERIFICATION","networkCallsPerformed",false,"databaseWritesPerformed",false)));}
    @PostMapping("/api/judge/benchmark/run") public ResponseEntity<?> runBenchmark(){try{return ApiResponse.success(200,"Benchmark tình huống tổng hợp đã chạy.",benchmark.run());}catch(BenchmarkService.BenchmarkRunningException e){return ApiResponse.failure(409,false,"Benchmark đang chạy. Vui lòng thử lại sau.",null,"BENCHMARK_ALREADY_RUNNING");}catch(Exception e){return ApiResponse.failure(500,false,"Không thể chạy benchmark trên máy chủ.",null,"BENCHMARK_RUN_FAILED");}}
    private Map<String,Object> readJson(String relative){try{java.nio.file.Path root=java.nio.file.Paths.get(config.projectRoot);java.nio.file.Path path=root.resolve(relative);if(!java.nio.file.Files.exists(path)){path=root.resolve("EDUASSISTANT").resolve(relative);}if(!java.nio.file.Files.exists(path))return null;return Json.object(Json.MAPPER.readValue(java.nio.file.Files.readAllBytes(path),Object.class));}catch(Exception e){return null;}}
}
